const {run, BIN} = require('/tmp/probe-output/run.js');
const {spawnSync} = require('child_process');

// very long output
for (const n of [1000, 65536, 131072, 100000]) {
  const buf = Buffer.from('Ä'.repeat(n), 'utf8');
  const r = run(buf);
  const out = Buffer.from(r.out, 'hex');
  const expect = Buffer.from('ä'.repeat(n) + '\n', 'utf8');
  console.log(JSON.stringify({n, inBytes: buf.length, code: r.code, outBytes: out.length,
    exactMatch: out.equals(expect), nNewlines: out.filter(b=>b===0x0a).length,
    lastByte: out[out.length-1], firstBytes: out.slice(0,8).toString('hex'), err: r.err.slice(0,100)}));
}

// separator-heavy long: 200k chars alternating
{
  const s = 'a!'.repeat(100000);
  const buf = Buffer.from(s,'utf8');
  const r = run(buf);
  const out = Buffer.from(r.out,'hex');
  const expect = Buffer.from(Array(100000).fill('a').join('_')+'\n','utf8');
  console.log(JSON.stringify({name:'alt 200k', code:r.code, outBytes:out.length, exactMatch: out.equals(expect), nNewlines: out.filter(b=>b===0x0a).length}));
}

// stdout when arg missing / help
for (const args of [[], ['--a'], ['--help']]) {
  const r = spawnSync(BIN, args, {encoding:'buffer'});
  console.log(JSON.stringify({args, code:r.status, stdoutHex:(r.stdout||Buffer.alloc(0)).toString('hex').slice(0,160), stdoutLen:(r.stdout||[]).length, stderrLen:(r.stderr||[]).length, stderr:(r.stderr||Buffer.alloc(0)).toString('utf8').slice(0,200)}));
}

// TTY: run under script(1) to give a pty
{
  const r = spawnSync('script', ['-qec', BIN + " --a 'Café X'", '/dev/null'], {encoding:'buffer'});
  console.log(JSON.stringify({name:'pty via script', code:r.status, out:(r.stdout||Buffer.alloc(0)).toString('hex'), err:(r.stderr||Buffer.alloc(0)).toString('utf8').slice(0,200)}));
}

// stdout redirected to file (not pipe)
{
  const fs=require('fs');
  const f='/tmp/probe-output/out.bin';
  const fd=fs.openSync(f,'w');
  const r=spawnSync(BIN,['--a','Café X'],{stdio:['ignore',fd,'pipe']});
  fs.closeSync(fd);
  console.log(JSON.stringify({name:'to file', code:r.status, out: fs.readFileSync(f).toString('hex')}));
}

// stdout closed
{
  const r=spawnSync(BIN,['--a','abc'],{stdio:['ignore','ignore','pipe']});
  console.log(JSON.stringify({name:'stdout to /dev/null-ish(ignore)', code:r.status, err:(r.stderr||Buffer.alloc(0)).toString('utf8').slice(0,200)}));
}

