// Reference: decode bytes as UTF-8 the Node/WHATWG way, then slugify (sep set from lead facts), then lower.
const PUNCT = '!"#$%&\'()*+,-./:;<=>?@[]^_`{|}~'; // ASCII punctuation EXCEPT backslash
const WS = ' \t\n\r\v\f';
const SEP = new Set((PUNCT + WS).split(''));
function slugify(s) {
  const parts = [];
  let cur = '';
  for (const ch of s) { if (SEP.has(ch)) { if (cur) parts.push(cur); cur=''; } else cur += ch; }
  if (cur) parts.push(cur);
  let j = parts.join('_');
  if (s.length > 0 && j === '') j = '_';
  return j.toLowerCase();
}

let mismatch = 0, tested = 0;
const rnd = (n)=>Math.floor(Math.random()*n);
const pool = [];
for (let b=0x80;b<=0xff;b++) pool.push(b);
pool.push(0x41,0x21,0x5c,0x7f,0x62);
for (let iter=0; iter<600; iter++) {
  const len = 1 + rnd(8);
  const bytes = Buffer.from(Array.from({length:len},()=>pool[rnd(pool.length)]));
  const decoded = bytes.toString('utf8');
  const expect = Buffer.from(slugify(decoded) + '\n', 'utf8');
  const r = run(bytes);
  const got = Buffer.from(r.out,'hex');
  tested++;
  if (!got.equals(expect) || r.code !== 0) {
    mismatch++;
    if (mismatch <= 12) console.log('MISMATCH', JSON.stringify({inHex:bytes.toString('hex'), code:r.code, gotHex:got.toString('hex'), expectHex:expect.toString('hex'), decodedEsc:JSON.stringify(decoded), err:r.err.slice(0,80)}));
  }
}
console.log(JSON.stringify({tested, mismatch}));

